values ('dialog_fq_star_100', 'fq_star_100', 'npc_centurion_valka', 'greeting', '[{"id": "greeting", "text": "The code demands action. Grand Justiciar Aurelius speaks at the Eternal Gate with the economy of lan...", "options": [{"text": "Tell me more.", "next": "lore", "action": ""}, {"text": "I''ll do it. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "I need to think about it.", "next": "exit", "action": "exit"}]}, {"id": "lore", "text": "Grand Justiciar Aurelius wrote the code in our home star''s ashes. It has never been wrong. When it says advance, we advance. Today it says: prove your worth.", "options": [{"text": "I''m ready. [Accept Quest]", "next": "accept", "action": "accept_quest"}, {"text": "Go back.", "next": "greeting", "action": ""}]}, {"id": "accept", "text": "Mission parameters: Travel to FORTRESS_KAELEN; Speak with npc_legion_general\n\nComplete with the honor the code demands.\n\nRewards: 50000 EXP · 25000 Currency · 12500 CRD · 10000 Reputation · Resonanted Astral Phase Crystal", "options": [{"text": "I''m on it.", "next": "exit", "action": "accept_quest"}]}, {"id": "exit", "text": "...", "options": []}]'::jsonb, 'dialog_quests.json', 728)
